/** Project keys are at most four characters (`TF`, `MAR2`). */
export const PROJECT_KEY_MAX_LENGTH = 4;

/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */
export function projectKeyFromName(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  const letters =
    words.length >= 2
      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
      : (words[0] ?? "task").slice(0, 3);
  return letters.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, PROJECT_KEY_MAX_LENGTH) || "TASK";
}

/**
 * A key that collides with nothing in `taken`. Same idea as `uniqueSlug`:
 * append 2, 3, … and trim the stem so the result never exceeds four characters.
 * Archived projects keep their keys, so callers pass every key in the workspace.
 */
export function uniqueProjectKey(key: string, taken: Iterable<string>): string {
  const used = new Set(Array.from(taken, (item) => item.toUpperCase()));
  const cleaned = key
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "")
    .slice(0, PROJECT_KEY_MAX_LENGTH);
  const base = cleaned.length >= 2 && /^[A-Z]/.test(cleaned) ? cleaned : "TASK";
  if (!used.has(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const tail = String(suffix);
    if (tail.length >= PROJECT_KEY_MAX_LENGTH) break;
    const candidate = `${base.slice(0, PROJECT_KEY_MAX_LENGTH - tail.length)}${tail}`;
    if (candidate.length >= 2 && /^[A-Z]/.test(candidate) && !used.has(candidate)) {
      return candidate;
    }
  }
  throw new InvalidSlugError(base, "exhausted unique key suffixes");
}

