export function projectKeyFromName(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  const letters =
    words.length >= 2
      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
      : (words[0] ?? "task").slice(0, 3);
  return letters.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, PROJECT_KEY_MAX_LENGTH) || "TASK";
}

/**
 * A key that collides with nothing in `taken`. Same idea as `uniqueSlug`:
 * append 2, 3, … and trim the stem so the result never exceeds four characters.
 * Archived projects keep their keys, so callers pass every key in the workspace.
