export function uniqueProjectKey(key: string, taken: Iterable<string>): string {
  const used = new Set(Array.from(taken, (item) => item.toUpperCase()));
  const cleaned = key
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "")
    .slice(0, PROJECT_KEY_MAX_LENGTH);
  const base = cleaned.length >= 2 && /^[A-Z]/.test(cleaned) ? cleaned : "TASK";
  if (!used.has(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const tail = String(suffix);
    if (tail.length >= PROJECT_KEY_MAX_LENGTH) break;
    const candidate = `${base.slice(0, PROJECT_KEY_MAX_LENGTH - tail.length)}${tail}`;
    if (candidate.length >= 2 && /^[A-Z]/.test(candidate) && !used.has(candidate)) {
      return candidate;
    }
  }
